// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;
    function setUp() public { c = new SimpleWallet(); }
    function testFuzz_property(uint256 amount) public {
        vm.assume(amount > 0);
        address sender = address(0x123);
        vm.assume(sender != c.owner());
        vm.deal(sender, amount);
        uint256 balanceBefore = address(c).balance;
        vm.prank(sender);
        (bool ok,) = address(c).call{value: amount}("");
        if (ok) {
            assertTrue(address(c).balance == balanceBefore + amount);
        } else {
            assertTrue(false, "receive should succeed in reference");
        }
    }
}
